/// still valid. The flag must not be combined with a cached plan, because a map-less cached command
/// would poison the plan for a later materialising terminal of the same shape.
/// </summary>
internal IPreparedQueryCommand<TResult> GetPreparedQueryCommand<TResult>(QueryCommand<TResult> queryCommand, bool createEnumerator, bool storeInCache, bool sequentialAccess, bool streamingRowsRequested, bool rawColumns, CancellationToken cancellationToken)
{
